# Generated by ChatGPT
$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot

$project = "cs528-project-0-508215"
$zone = "us-east1-b"
$instance = "hw5-db"
$bucket = "ec528hw2"
$serviceAccount = "hw6-models@$project.iam.gserviceaccount.com"
$vm = "hw6-models-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
$vmCreated = $false

# Turn a failed gcloud command into a PowerShell error.
function Invoke-Gcloud {
    & gcloud @args
    if ($LASTEXITCODE -ne 0) {
        throw "gcloud failed with exit code $LASTEXITCODE"
    }
}

try {
    Invoke-Gcloud sql instances patch $instance `
        --activation-policy=ALWAYS --project=$project --quiet

    Invoke-Gcloud compute instances create $vm `
        --zone=$zone `
        --machine-type=e2-standard-2 `
        --image-family=debian-12 `
        --image-project=debian-cloud `
        --boot-disk-size=10GB `
        --boot-disk-type=pd-standard `
        --service-account=$serviceAccount `
        --scopes=cloud-platform `
        --project=$project --quiet

    $vmCreated = $true

    # Wait for SSH to become available.
    $sshReady = $false
    for ($attempt = 1; $attempt -le 12; $attempt++) {
        & gcloud compute ssh $vm `
            --zone=$zone --project=$project `
            --command="true"

        if ($LASTEXITCODE -eq 0) {
            $sshReady = $true
            break
        }

        Start-Sleep -Seconds 10
    }

    if (-not $sshReady) {
        throw "Could not connect to the VM."
    }

    Invoke-Gcloud compute scp `
        models.py requirements.txt vm-run.sh ../hw5/app.env `
        "${vm}:/tmp/" `
        --zone=$zone --project=$project

    $command = "mkdir -p ~/hw6 && mv /tmp/models.py /tmp/requirements.txt /tmp/vm-run.sh /tmp/app.env ~/hw6/ && cd ~/hw6 && sed -i 's/\r$//' vm-run.sh app.env && bash vm-run.sh"

    Invoke-Gcloud compute ssh $vm `
        --zone=$zone --project=$project `
        --command=$command
}
finally {
    # Attempt both cleanup operations, even if one fails.
    try {
        if ($vmCreated) {
            Invoke-Gcloud compute instances delete $vm `
                --zone=$zone --project=$project --quiet
        }
    }
    finally {
        Invoke-Gcloud sql instances patch $instance `
            --activation-policy=NEVER --project=$project --quiet
    }
}

Write-Host "Country predictions from the bucket:"
Invoke-Gcloud storage cat "gs://$bucket/hw6/country_predictions.csv"

Write-Host "Income predictions from the bucket:"
Invoke-Gcloud storage cat "gs://$bucket/hw6/income_predictions.csv"

Write-Host "Final metrics from the bucket:"
Invoke-Gcloud storage cat "gs://$bucket/hw6/metrics.json"

Write-Host "Completed. Database stopped and VM deleted."